<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';import ScreenCanvas from './ScreenCanvas.vue';import {bounds,snapPosition,scaleSelection} from '../layout.js';
const props=defineProps({project:Object,selectedIds:Array,playing:Boolean,assets:Object});const emit=defineEmits(['select','selection','record','add']);const viewport=ref(),stage=ref(),scale=ref(.4),zoom=ref(1),guides=ref([]),marquee=ref(null),space=ref(false),hand=ref(false),panning=ref(false);let observer,drag=null,raf,pending,clickCanvas=false;
const selected=computed(()=>props.project.nodes.filter(n=>props.selectedIds.includes(n.id)&&n.visible)),box=computed(()=>bounds(selected.value));const rulerX=computed(()=>Array.from({length:Math.ceil(props.project.width/100)+1},(_,i)=>i*100)),rulerY=computed(()=>Array.from({length:Math.ceil(props.project.height/100)+1},(_,i)=>i*100));
function fit(){if(!viewport.value)return;const r=viewport.value.getBoundingClientRect();scale.value=Math.max(.06,Math.min((r.width-88)/props.project.width,(r.height-100)/props.project.height))*zoom.value;}
function at(e){const r=stage.value.getBoundingClientRect();return {x:(e.clientX-r.left)/scale.value,y:(e.clientY-r.top)/scale.value};}
function panDown(e){if(e.button===1||space.value||hand.value){e.preventDefault();drag={kind:'pan',x:e.clientX,y:e.clientY,left:viewport.value.scrollLeft,top:viewport.value.scrollTop};panning.value=true;viewport.value.setPointerCapture(e.pointerId);return true;}return false;}
function nodeDown(node,e){if(panDown(e)||e.button!==0)return;e.stopPropagation();if(node.locked)return;emit('select',node,e.shiftKey||e.metaKey||e.ctrlKey);nextTick(()=>{const group=props.project.nodes.filter(n=>props.selectedIds.includes(n.id)&&!n.locked),rect=bounds(group);if(!rect)return;drag={kind:'move',point:at(e),box:{...rect},original:group.map(n=>({id:n.id,x:n.x,y:n.y,w:n.w,h:n.h}))};viewport.value.setPointerCapture(e.pointerId);});}
function canvasDown(e){if(panDown(e)||e.button!==0)return;if(e.target.closest('.aw-screen-widget,.aw-selection'))return;const p=at(e);clickCanvas=true;drag={kind:'marquee',point:p,extend:e.shiftKey,previous:[...props.selectedIds]};if(!e.shiftKey)emit('selection',[]);marquee.value={x:p.x,y:p.y,w:0,h:0};viewport.value.setPointerCapture(e.pointerId);}
function resizeDown(e,handle){e.preventDefault();e.stopPropagation();if(!box.value)return;drag={kind:'resize',handle,point:at(e),box:{...box.value},original:selected.value.filter(n=>!n.locked).map(n=>({id:n.id,x:n.x,y:n.y,w:n.w,h:n.h}))};viewport.value.setPointerCapture(e.pointerId);}
function applyMove(e){if(!drag)return;if(drag.kind==='pan'){viewport.value.scrollLeft=drag.left-(e.clientX-drag.x);viewport.value.scrollTop=drag.top-(e.clientY-drag.y);return;}const p=at(e),dx=p.x-drag.point.x,dy=p.y-drag.point.y;
 if(drag.kind==='marquee'){marquee.value={x:Math.min(p.x,drag.point.x),y:Math.min(p.y,drag.point.y),w:Math.abs(dx),h:Math.abs(dy)};return;}
 const originals=drag.original,items=props.project.nodes.filter(n=>originals.some(o=>o.id===n.id));if(drag.kind==='move'){let x=drag.box.x+dx,y=drag.box.y+dy;if(props.project.snap&&!e.altKey){const snap=snapPosition({...drag.box,x,y},props.project.nodes.filter(n=>!originals.some(o=>o.id===n.id)),props.project.width,props.project.height,props.project.grid,8/scale.value);x=snap.x;y=snap.y;guides.value=snap.guides;}else guides.value=[];for(const n of items){const o=originals.find(o=>o.id===n.id);n.x=Math.round(o.x+x-drag.box.x);n.y=Math.round(o.y+y-drag.box.y);}}
 if(drag.kind==='resize'){const b=drag.box,h=drag.handle;let x=b.x,y=b.y,w=b.w,hgt=b.h;if(h.includes('e'))w=Math.max(24,b.w+dx);if(h.includes('s'))hgt=Math.max(24,b.h+dy);if(h.includes('w')){w=Math.max(24,b.w-dx);x=b.x+b.w-w;}if(h.includes('n')){hgt=Math.max(24,b.h-dy);y=b.y+b.h-hgt;}if(e.shiftKey){const ratio=b.w/b.h;if(Math.abs(dx)>Math.abs(dy))hgt=w/ratio;else w=hgt*ratio;if(h.includes('w'))x=b.x+b.w-w;if(h.includes('n'))y=b.y+b.h-hgt;}
 const clones=originals.map(o=>({...o}));scaleSelection(clones,b,{x,y,w,h:hgt});for(const n of items){const o=clones.find(o=>o.id===n.id);Object.assign(n,{x:Math.round(o.x),y:Math.round(o.y),w:Math.round(o.w),h:Math.round(o.h)});}}
}
function move(e){if(!drag)return;pending={clientX:e.clientX,clientY:e.clientY,altKey:e.altKey,shiftKey:e.shiftKey};if(!raf)raf=requestAnimationFrame(()=>{raf=null;applyMove(pending);});}
function finish(e){if(!drag)return;if(raf){cancelAnimationFrame(raf);raf=null;applyMove(pending);}if(drag.kind==='marquee'){const r=marquee.value,ids=props.project.nodes.filter(n=>n.visible&&!n.locked&&n.x<r.x+r.w&&n.x+n.w>r.x&&n.y<r.y+r.h&&n.y+n.h>r.y).map(n=>n.id);emit('selection',drag.extend?[...new Set([...drag.previous,...ids])]:ids);}else if(drag.kind!=='pan')emit('record');drag=null;guides.value=[];marquee.value=null;panning.value=false;if(viewport.value?.hasPointerCapture(e.pointerId))viewport.value.releasePointerCapture(e.pointerId);}
function wheel(e){if(e.ctrlKey||e.metaKey){e.preventDefault();zoom.value=Math.min(4,Math.max(.25,zoom.value*(e.deltaY>0?.93:1.07)));fit();}}
function key(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.code==='Space'){e.preventDefault();space.value=e.type==='keydown';}}
function drop(e){e.preventDefault();const type=e.dataTransfer.getData('astra/component');if(type){const p=at(e);emit('add',type,p);}}
onMounted(()=>{observer=new ResizeObserver(fit);observer.observe(viewport.value);viewport.value.addEventListener('wheel',wheel,{passive:false});window.addEventListener('keydown',key);window.addEventListener('keyup',key);fit();});watch(()=>[props.project.width,props.project.height],()=>{zoom.value=1;fit();});onBeforeUnmount(()=>{cancelAnimationFrame(raf);observer?.disconnect();viewport.value?.removeEventListener('wheel',wheel);window.removeEventListener('keydown',key);window.removeEventListener('keyup',key);});
function changeZoom(delta){zoom.value=Math.max(.25,Math.min(4,zoom.value+delta));fit();}defineExpose({fit(){zoom.value=1;fit();},changeZoom,hand});
</script>
<template><div class="aw-editor-region"><div class="aw-ruler-h"><span v-for="x in rulerX" :key="x" :style="{left:44+x*scale+'px'}">{{x}}</span></div><div class="aw-ruler-v"><span v-for="y in rulerY" :key="y" :style="{top:48+y*scale+'px'}">{{y}}</span></div><div ref="viewport" class="aw-canvas-viewport" :class="{panning:space||hand||panning}" @pointerdown="canvasDown" @pointermove="move" @pointerup="finish" @pointercancel="finish" @dragover.prevent @drop="drop"><div class="aw-canvas-space" :style="{width:Math.max(project.width*scale+88,100)+'px',height:Math.max(project.height*scale+100,100)+'px'}"><div ref="stage" class="aw-stage" :style="{width:project.width+'px',height:project.height+'px',transform:`scale(${scale})`}"><ScreenCanvas :project="project" :playing="playing" :assets="assets" :selected-ids="selectedIds" :interactive="false" @node-down="nodeDown" @node-double-click="(node,e)=>{e.stopPropagation();emit('selection',[node.id])}">
 <div v-if="project.grid" class="aw-editor-grid" :style="{backgroundSize:'20px 20px'}"></div><div v-for="(g,i) in guides" :key="i" class="aw-alignment-guide" :class="g.axis" :style="g.axis==='x'?{left:g.position+'px'}:{top:g.position+'px'}"></div>
 <div v-if="box" class="aw-selection" :style="{left:box.x+'px',top:box.y+'px',width:box.w+'px',height:box.h+'px','--handle-scale':1/scale}"><span class="aw-selection-label">{{selected.length>1?selected.length+' 个组件':selected[0]?.name}} <i>{{Math.round(box.w)}} × {{Math.round(box.h)}}</i></span><button v-for="handle in ['nw','n','ne','e','se','s','sw','w']" :key="handle" class="aw-resize-handle" :class="handle" :aria-label="'从'+handle+'方向缩放'" @pointerdown="resizeDown($event,handle)"></button></div><div v-if="marquee" class="aw-marquee" :style="{left:marquee.x+'px',top:marquee.y+'px',width:marquee.w+'px',height:marquee.h+'px'}"></div>
 </ScreenCanvas></div></div></div><div class="aw-canvas-floating"><span><i></i>{{project.width}} × {{project.height}}</span><div><button aria-label="缩小画布" @click="changeZoom(-.25)">−</button><button class="zoom-value" @click="zoom=1;fit()">{{Math.round(scale*100)}}%</button><button aria-label="放大画布" @click="changeZoom(.25)">+</button></div><button aria-label="适应画布" @click="zoom=1;fit()">⌖</button></div><div class="aw-canvas-hint">拖拽组件开始设计 <span>·</span> Shift 多选 <span>·</span> Space 拖动画布</div></div></template>
